struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float3 proceduralScene(float2 uv, float t)
{
    float3 col = float3(0.1f, 0.05f, 0.15f);
    float2 c1 = float2(0.3f + 0.2f * sin(t), 0.4f + 0.2f * cos(t * 0.7f));
    float d1 = length(uv - c1);
    col = lerp(float3(1.0f, 0.3f, 0.1f), col, smoothstep(0.08f, 0.12f, d1));
    float2 c2 = float2(0.7f + 0.15f * cos(t * 1.2f), 0.6f + 0.15f * sin(t * 0.9f));
    float d2 = length(uv - c2);
    col = lerp(float3(0.1f, 0.5f, 1.0f), col, smoothstep(0.06f, 0.1f, d2));
    float2 c3 = float2(0.5f, 0.5f + 0.3f * sin(t * 0.5f));
    float d3 = length(uv - c3);
    col = lerp(float3(0.2f, 1.0f, 0.3f), col, smoothstep(0.1f, 0.15f, d3));
    col += 0.15f * float3(uv.x, 0.5f, uv.y);
    return col;
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001f;
    float mx = mouse_x / resolution_x;
    float pixelCount = lerp(8.0f, 128.0f, mx);
    float2 uv = floor(i.uv * pixelCount) / pixelCount;
    float3 col = proceduralScene(uv, t);
    return float4(col, 1.0f);
}
